<script lang="ts">
  import { ui } from '$lib/i18n';
  import { defaultKitchenEquipment,kitchenLengthMm,kitchenUnitLabels,type KitchenEquipment } from '$lib/utils/kitchenEquipment';
  let {equipment=$bindable(defaultKitchenEquipment()),layout}:{equipment?:KitchenEquipment;layout:string}=$props();
</script>
<section class="equipment" aria-label={$ui("Éléments de cuisine par défaut")}>
  <h3>{$ui("Votre cuisine déjà équipée")}</h3><p>{$ui("Meubles bas et hauts, tiroirs, évier, four, plaque et hotte sont ajoutés dès la création.")}</p>
  <div class="dimensions">{#each [{key:'totalHeightMm',label:'Hauteur totale (cm)',min:1800,max:3000},{key:'baseHeightMm',label:'Hauteur meubles bas (cm)',min:700,max:1100},{key:'baseDepthMm',label:'Profondeur meubles bas (cm)',min:500,max:800},{key:'upperHeightMm',label:'Hauteur meubles hauts (cm)',min:400,max:1100},{key:'upperDepthMm',label:'Profondeur meubles hauts (cm)',min:250,max:450}] as field}<label>{$ui(field.label)}<input type="number" min={(field.min) / 10} max={(field.max) / 10} step="1" bind:value={() => (equipment[field.key as 'totalHeightMm'|'baseHeightMm'|'baseDepthMm'|'upperHeightMm'|'upperDepthMm']) / 10, value => equipment[field.key as 'totalHeightMm'|'baseHeightMm'|'baseDepthMm'|'upperHeightMm'|'upperDepthMm'] = value == null ? NaN : value * 10} /></label>{/each}</div>
  <h4>{$ui("Composition du linéaire principal")}</h4><div class="units">{#each kitchenUnitLabels as label,i}<label>{$ui(label)}<span><input type="number" min="30" max="120" step="1" bind:value={() => (equipment.widthsMm[i]) / 10, value => equipment.widthsMm[i] = value == null ? NaN : value * 10} /> {$ui("cm")}</span></label>{/each}</div>
  <p class="length">{$ui("Longueur calculée :")} <strong>{Math.round(kitchenLengthMm(equipment)/10)} {$ui("cm")}</strong> {$ui("· Meubles bas et hauts :")} {Math.round(equipment.widthsMm.reduce((a,b)=>a+b,0)/10)} {$ui("cm")}</p>
  <label class="toggle"><input type="checkbox" bind:checked={equipment.fridge} /> {$ui("Ajouter la colonne réfrigérateur")}</label>
  {#if equipment.fridge}<div class="dimensions"><label>{$ui("Largeur de la colonne réfrigérateur (cm)")}<input type="number" min="55" max="90" step="1" bind:value={() => (equipment.fridgeWidthMm) / 10, value => equipment.fridgeWidthMm = value == null ? NaN : value * 10} /></label><label>{$ui("Position du réfrigérateur")}<select bind:value={equipment.fridgeSide}><option value="left">{$ui("À gauche")}</option><option value="right">{$ui("À droite")}</option></select></label></div>{/if}
  {#if ['l-shaped','u-shaped','galley','island'].includes(layout)}<div class="dimensions"><label>{$ui("Longueur")} {$ui(layout==='island'?'de l’îlot':'du retour')} (cm)<input type="number" min="90" max="500" step="1" bind:value={() => (equipment.returnLengthMm) / 10, value => equipment.returnLengthMm = value == null ? NaN : value * 10} /></label>{#if layout==='l-shaped'}<label>{$ui("Côté du retour")}<select bind:value={equipment.returnSide}><option value="left">{$ui("À gauche")}</option><option value="right">{$ui("À droite")}</option></select></label>{/if}</div>{/if}
  <p>{$ui("Crédence et plan de travail inclus. L’espace entre meubles bas et hauts est de")} {Math.round((equipment.totalHeightMm-equipment.baseHeightMm-equipment.upperHeightMm)/10)} cm.</p>
</section>
<style>.equipment{margin-top:24px;border-top:1px solid #dce0eb;padding-top:20px;color:#1e2447}h3{font-size:18px;font-weight:700}h4{font-size:14px;font-weight:700;margin:20px 0 12px}.equipment p{font-size:13px;color:#4e5c78;line-height:1.6;margin:10px 0}.dimensions{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin:16px 0}label{font-size:13px;font-weight:600}input:not([type=checkbox]),select{display:block;padding:9px 10px;border:1px solid #bbc5df;border-radius:7px;background:white;margin-top:6px;width:100%}.units{display:grid;gap:8px}.units label{display:flex;justify-content:space-between;align-items:center;gap:12px}.units span{display:flex;align-items:center;gap:8px;font-weight:400}.units input{width:95px;margin:0}.toggle{display:flex;gap:8px;align-items:center;margin:18px 0}.toggle input{accent-color:#1e2447;width:18px;height:18px}.length{background:#edf0f8;padding:12px;border-radius:7px}@media(max-width:650px){.dimensions{grid-template-columns:1fr}.units label{font-size:12px}}</style>
